// Tang Nano 20K: two groups of three LEDs alternate every half second.
// The FPGA drives the LEDs through a register, rather than constant VCC/GND nets.
module top #(
    parameter integer HALF_PERIOD = 13_500_000
)(
    input wire clk,
    output wire [5:0] led_n
);
    reg [23:0] divider = 0;
    reg phase = 0;
    always @(posedge clk) begin
        if (divider == HALF_PERIOD - 1) begin
            divider <= 0;
            phase <= ~phase;
        end else begin
            divider <= divider + 1'b1;
        end
    end
    // LEDs are active low. Exactly three should be on in either phase.
    assign led_n = phase ? 6'b010101 : 6'b101010;
endmodule

// Onboard 27 MHz clock and active-low LEDs; no external wiring.
IO_LOC "clk" 4;
IO_PORT "clk" PULL_MODE=UP IO_TYPE=LVCMOS33;
IO_LOC "led_n[0]" 15;
IO_PORT "led_n[0]" PULL_MODE=UP DRIVE=8 IO_TYPE=LVCMOS33;
IO_LOC "led_n[1]" 16;
IO_PORT "led_n[1]" PULL_MODE=UP DRIVE=8 IO_TYPE=LVCMOS33;
IO_LOC "led_n[2]" 17;
IO_PORT "led_n[2]" PULL_MODE=UP DRIVE=8 IO_TYPE=LVCMOS33;
IO_LOC "led_n[3]" 18;
IO_PORT "led_n[3]" PULL_MODE=UP DRIVE=8 IO_TYPE=LVCMOS33;
IO_LOC "led_n[4]" 19;
IO_PORT "led_n[4]" PULL_MODE=UP DRIVE=8 IO_TYPE=LVCMOS33;
IO_LOC "led_n[5]" 20;
IO_PORT "led_n[5]" PULL_MODE=UP DRIVE=8 IO_TYPE=LVCMOS33;
